import React, { useState, useEffect } from "react";

const API = "http://localhost:5000";

// ─── Simple fetch helpers ─────────────────────────────────────────────────────
const get = (url) => fetch(API + url).then((r) => r.json());
const post = (url, data) =>
  fetch(API + url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  }).then((r) => r.json());
const put = (url, data) =>
  fetch(API + url, {
    method: "PUT",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  }).then((r) => r.json());
const del = (url) => fetch(API + url, { method: "DELETE" }).then((r) => r.json());

// ─── APP ──────────────────────────────────────────────────────────────────────
export default function App() {
  // State
  const [teachers, setTeachers] = useState([]);
  const [students, setStudents] = useState([]);
  const [courses, setCourses] = useState([]);

  const [teacherName, setTeacherName] = useState("");
  const [studentName, setStudentName] = useState("");
  const [selectedTeacher, setSelectedTeacher] = useState("");
  const [courseTitle, setCourseTitle] = useState("");

  const [editTeacher, setEditTeacher] = useState(null); // { id, name }
  const [editStudent, setEditStudent] = useState(null); // { id, name, teacherId }
  const [editCourse, setEditCourse] = useState(null);   // { id, title }

  // Load all data on mount
  useEffect(() => {
    loadAll();
  }, []);

  async function loadAll() {
    setTeachers(await get("/teachers"));
    setStudents(await get("/students"));
    setCourses(await get("/courses"));
  }

  // ── TEACHER OPERATIONS ──────────────────────────────────────────────────────
  async function addTeacher() {
    if (!teacherName) return alert("Enter teacher name");
    await post("/teachers", { name: teacherName });
    setTeacherName("");
    loadAll();
  }

  async function updateTeacher() {
    await put(`/teachers/${editTeacher.id}`, { name: editTeacher.name });
    setEditTeacher(null);
    loadAll();
  }

  async function deleteTeacher(id) {
    await del(`/teachers/${id}`);
    loadAll();
  }

  // ── STUDENT OPERATIONS (ONE-TO-MANY) ────────────────────────────────────────
  async function addStudent() {
    if (!studentName || !selectedTeacher) return alert("Enter name and select teacher");
    await post("/students", { name: studentName, teacherId: selectedTeacher });
    setStudentName("");
    loadAll();
  }

  async function updateStudent() {
    await put(`/students/${editStudent.id}`, {
      name: editStudent.name,
      teacherId: editStudent.teacherId,
    });
    setEditStudent(null);
    loadAll();
  }

  async function deleteStudent(id) {
    await del(`/students/${id}`);
    loadAll();
  }

  // ── COURSE OPERATIONS ───────────────────────────────────────────────────────
  async function addCourse() {
    if (!courseTitle) return alert("Enter course title");
    await post("/courses", { title: courseTitle });
    setCourseTitle("");
    loadAll();
  }

  async function updateCourse() {
    await put(`/courses/${editCourse.id}`, { title: editCourse.title });
    setEditCourse(null);
    loadAll();
  }

  async function deleteCourse(id) {
    await del(`/courses/${id}`);
    loadAll();
  }

  // ── ENROLL / UNENROLL (MANY-TO-MANY) ────────────────────────────────────────
  async function enroll(courseId, studentId) {
    await post(`/courses/${courseId}/enroll/${studentId}`);
    loadAll();
  }

  async function unenroll(courseId, studentId) {
    await post(`/courses/${courseId}/unenroll/${studentId}`);
    loadAll();
  }

  // ── RENDER ──────────────────────────────────────────────────────────────────
  return (
    <div style={{ padding: 20, fontFamily: "Arial" }}>
      <h1>School App — React + MongoDB CRUD</h1>

      {/* ====== SECTION 1: TEACHERS ====== */}
      <hr />
      <h2>Teachers (One-to-Many Parent)</h2>
      <p>One teacher can have MANY students</p>

      <input
        placeholder="Teacher name"
        value={teacherName}
        onChange={(e) => setTeacherName(e.target.value)}
      />
      <button onClick={addTeacher}>Add Teacher</button>

      <ul>
        {teachers.map((t) => (
          <li key={t._id}>
            {editTeacher?.id === t._id ? (
              <>
                <input
                  value={editTeacher.name}
                  onChange={(e) =>
                    setEditTeacher({ ...editTeacher, name: e.target.value })
                  }
                />
                <button onClick={updateTeacher}>Save</button>
                <button onClick={() => setEditTeacher(null)}>Cancel</button>
              </>
            ) : (
              <>
                <strong>{t.name}</strong>
                <button onClick={() => setEditTeacher({ id: t._id, name: t.name })}>
                  Edit
                </button>
                <button onClick={() => deleteTeacher(t._id)}>Delete</button>
              </>
            )}
          </li>
        ))}
      </ul>

      {/* ====== SECTION 2: STUDENTS (ONE-TO-MANY) ====== */}
      <hr />
      <h2>Students — One-to-Many Relationship</h2>
      <p>Each student belongs to exactly ONE teacher (Foreign Key: teacher_id)</p>

      <input
        placeholder="Student name"
        value={studentName}
        onChange={(e) => setStudentName(e.target.value)}
      />
      <select
        value={selectedTeacher}
        onChange={(e) => setSelectedTeacher(e.target.value)}
      >
        <option value="">-- Select Teacher --</option>
        {teachers.map((t) => (
          <option key={t._id} value={t._id}>
            {t.name}
          </option>
        ))}
      </select>
      <button onClick={addStudent}>Add Student</button>

      <ul>
        {students.map((s) => (
          <li key={s._id}>
            {editStudent?.id === s._id ? (
              <>
                <input
                  value={editStudent.name}
                  onChange={(e) =>
                    setEditStudent({ ...editStudent, name: e.target.value })
                  }
                />
                <select
                  value={editStudent.teacherId}
                  onChange={(e) =>
                    setEditStudent({ ...editStudent, teacherId: e.target.value })
                  }
                >
                  {teachers.map((t) => (
                    <option key={t._id} value={t._id}>
                      {t.name}
                    </option>
                  ))}
                </select>
                <button onClick={updateStudent}>Save</button>
                <button onClick={() => setEditStudent(null)}>Cancel</button>
              </>
            ) : (
              <>
                <strong>{s.name}</strong>
                {" → Teacher: "}
                <em>{s.teacher?.name || "None"}</em>
                <button
                  onClick={() =>
                    setEditStudent({
                      id: s._id,
                      name: s.name,
                      teacherId: s.teacher?._id || "",
                    })
                  }
                >
                  Edit
                </button>
                <button onClick={() => deleteStudent(s._id)}>Delete</button>
              </>
            )}
          </li>
        ))}
      </ul>

      {/* ====== SECTION 3: COURSES + ENROLL (MANY-TO-MANY) ====== */}
      <hr />
      <h2>Courses — Many-to-Many Relationship</h2>
      <p>
        One student can enroll in MANY courses. One course can have MANY
        students.
      </p>

      <input
        placeholder="Course title"
        value={courseTitle}
        onChange={(e) => setCourseTitle(e.target.value)}
      />
      <button onClick={addCourse}>Add Course</button>

      {courses.map((c) => {
        const enrolledIds = c.students.map((s) => s._id);
        return (
          <div key={c._id} style={{ border: "1px solid #ccc", margin: 10, padding: 10 }}>
            {editCourse?.id === c._id ? (
              <>
                <input
                  value={editCourse.title}
                  onChange={(e) =>
                    setEditCourse({ ...editCourse, title: e.target.value })
                  }
                />
                <button onClick={updateCourse}>Save</button>
                <button onClick={() => setEditCourse(null)}>Cancel</button>
              </>
            ) : (
              <>
                <strong>Course: {c.title}</strong>
                <button
                  onClick={() => setEditCourse({ id: c._id, title: c.title })}
                >
                  Edit
                </button>
                <button onClick={() => deleteCourse(c._id)}>Delete</button>
              </>
            )}

            <p>Enrolled Students: {c.students.map((s) => s.name).join(", ") || "None"}</p>

            {/* Enroll / Unenroll buttons for each student */}
            <div>
              {students.map((s) =>
                enrolledIds.includes(s._id) ? (
                  <button key={s._id} onClick={() => unenroll(c._id, s._id)}>
                    Unenroll {s.name}
                  </button>
                ) : (
                  <button key={s._id} onClick={() => enroll(c._id, s._id)}>
                    Enroll {s.name}
                  </button>
                )
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}
